def _is_all_questions_tolerant(r: str) -> bool:
    sentences = _split_sentences(r)
    sentences = _apply_truncation_guard(sentences)
    if not sentences:
        return False
    q_count = sum(1 for s in sentences if s.rstrip().endswith("?"))
    total = len(sentences)
    if total <= 2:
        return all(s.rstrip().endswith("?") for s in sentences)
    return (total - q_count) <= 2 and q_count > total * 0.5

def _is_all_statements_tolerant(r: str) -> bool:
    sentences = _split_sentences(r)
    sentences = _apply_truncation_guard(sentences)
    if not sentences:
        return False
    q_count = sum(1 for s in sentences if s.rstrip().endswith("?"))
    total = len(sentences)
    if total <= 2:
        return not any(s.rstrip().endswith("?") for s in sentences)
    return q_count <= 2 and (total - q_count) > total * 0.5
